class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Detects hallucinations by measuring the average negative log-probability of generated tokens.

        Signal: Mean Negative Log-Likelihood (M-NLL) of the generated sequence.
        Aggregation: Arithmetic mean across tokens within each sequence.

        Hypothesis: Hallucinated tokens are systematically assigned lower conditional probabilities 
        by the model compared to factual tokens, leading to a higher average NLL per token. 
        Summing NLL (previous approach) was suboptimal as it conflated sequence length with token quality.
        """
        # Calculate mean negative log-prob for each sequence
        # sequence_logprobs is List[np.ndarray], inner shape (n_i - 1,)
        # We compute -sum(log_probs) / count for each sequence

        mean_neg_logprobs = []
        for seq_logprobs in stats["sequence_logprobs"]:
            if len(seq_logprobs) == 0:
                mean_neg_logprobs.append(0.0)
            else:
                neg_sum = -np.sum(seq_logprobs)
                mean_val = neg_sum / len(seq_logprobs)
                mean_neg_logprobs.append(mean_val)

        return np.array(mean_neg_logprobs, dtype=np.float32)

class HallucinationDetector:
    """
    Detects hallucinations by measuring the average negative log-probability (per-token perplexity) 
    of the generated sequence. 
    Hypothesis: Hallucinated claims contain specific low-probability tokens (rare entities/facts) 
    that inflate the mean NLP more than long truthful sequences, which are composed of common tokens.
    """
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        # sequence_logprobs: List[np.ndarray] of length N, inner 1d array has length n_i - 1.
        # We compute the mean negative log-probability for each sequence.
        # This is equivalent to log(perplexity).

        neg_logprobs_list = []
        for seq_logprobs in stats["sequence_logprobs"]:
            # Ensure we handle the case where the sequence might be empty after slicing
            if len(seq_logprobs) == 0:
                neg_logprobs_list.append(np.array([0.0], dtype=np.float32))
            else:
                neg_logprobs_list.append(np.mean(seq_logprobs, dtype=np.float32))

        return np.array(neg_logprobs_list, dtype=np.float32)

